mapper.select:
select hbm.BP_CODE as bp_code, t.chance_bp_id, t.chance_id, t.bp_id, t.bp_name, hbm.bp_name as bp_id_n, t.bp_eng_name, t.bp_type, t.note, t.guar_method, (select v.MEANING from sys_code_value_b_v v where v.CODE='HCLCB.GUAR_METHOD' and v.code_value=t.guar_method) as guar_method_n, hbm.GROUP_COMPANIES, HBM.ECONOMIC_INDU_CLASSIFY, (SELECT S.DESCRIPTION FROM HLS_STAT_CLASS S WHERE to_char(S.CLASS_ID)=HBM.ECONOMIC_INDU_CLASSIFY) ECONOMIC_INDU_CLASSIFY_N, (select scv.MEANING from sys_code_b sc,sys_code_value_b scv where sc.CODE_ID = scv.CODE_ID and sc.CODE = 'BP.BP_MASTER_ROLE' and scv.value = t.bp_type) bp_type_n, hbm.bp_class, t.credit_amount, t.credit_amount_used, t.credit_project_id, (select max(contract_number) as contract_number from prj_project where ref_project_id = t.credit_project_id and contract_number is not null) as contract_number from HLS_CREDIT_LINE_CHANCE_BP t, hls_bp_master hbm where t.bp_id=hbm.BP_ID
AND t.CHANCE_ID=#{chanceId}
AND t.bp_type in ('TENANT')

SELECT *
FROM   hls_credit_line_chance_bp hcb

        1=1

       and  hcb.bp_id = #{bpId}


         and  hcb.chance_id = #{chanceId}


        and hcb.bp_type = #{bpType}

SELECT * FROM hls_credit_line_chance_bp hcb
1=1 and hcb.bp_type = 'TENANT'
and hcb.chance_id = #{chanceId}

SELECT * FROM hls_credit_line_chance_bp hcb
1=1
and hcb.chance_id = #{chanceId}

SELECT wm_concat(hcb.bp_id) as tenant_sec_id , wm_concat(hcb.bp_name) as tenant_sec_id_n FROM hls_credit_line_chance_bp hcb
1=1 and hcb.bp_type = 'TENANT_SEC'
and hcb.chance_id = #{chanceId}

SELECT wm_concat(hcb.bp_id) as guarantor_id FROM hls_credit_line_chance_bp hcb
1=1 and hcb.bp_type = 'WARRANTOR' and hcb.bp_class = 'ORG'
and hcb.chance_id = #{chanceId}

SELECT wm_concat(hcb.bp_id) as guarantor_np_id FROM hls_credit_line_chance_bp hcb
1=1 and hcb.bp_type = 'WARRANTOR' and hcb.bp_class = 'NP'
and hcb.chance_id = #{chanceId}
